const clone=x=>JSON.parse(JSON.stringify(x));
const distance=(a,b)=>Math.hypot((a?.x||0)-(b?.x||0),(a?.z||0)-(b?.z||0));
export class StreetLife {
 constructor({seed=15426,hooks={}}={}){this.hooks=hooks;this.reset(seed);}
 reset(seed=15426){this.state={version:1,seed,rng:seed>>>0||1,time:0,nextAt:3,active:null,played:{},memories:{},log:[]};return this;}
 random(){let x=this.state.rng;x^=x<<13;x^=x>>>17;x^=x<<5;this.state.rng=x>>>0;return this.state.rng/4294967296;}
 actors(ctx){return Array.isArray(ctx.actors)?Object.fromEntries(ctx.actors.map(a=>[a.id,a])):ctx.actors||{};}
 eligible(scene,ctx){const a=this.actors(ctx),lead=a[scene.cast[0]],record=this.state.played[scene.id];return lead&&!lead.hidden&&!scene.cast.some(id=>!a[id]||a[id].hidden||distance(a[id],lead)>12)&&distance(ctx.player,lead)<20&&scene.phases.includes(ctx.phase||'morning')&&(ctx.tension||0)<(scene.maxTension||72)&&(!record||record.count<2&&this.state.time-record.at>(record.status==='interrupted'?35:180));}
 emit(type,data,ctx,out){const event={type,time:this.state.time,...data};out.push(event);const actors=this.actors(ctx),speaker=actors[data.actorId],audible=!speaker||distance(ctx.player,speaker)<24;const meta={...event,distance:speaker?distance(ctx.player,speaker):0};if(type==='say'&&audible)this.hooks.say?.(data.actorId,data.line,meta);if(type==='sound'&&audible)this.hooks.sound?.(data.cue,meta);if(type==='gesture')this.hooks.gesture?.(data.actorId,data.kind,meta);if(type==='effect')this.hooks.effect?.(event);if(type==='crowd')this.hooks.crowd?.(event);return event;}
 tick(dt,ctx={}){const out=[];if(ctx.paused||!Number.isFinite(dt)||dt<0)return out;this.state.time+=Math.min(dt,5);const s=this.state;let a=s.active;
 if(a&&(ctx.busy||ctx.pursuit||!this.castPresent(a,ctx)||a.interjection&&distance(ctx.player,this.actors(ctx)[STREET_SCENES.find(e=>e.id===a.id).cast[0]])>10)){this.finish('interrupted');return out;}
 if(!a&&s.time>=s.nextAt&&!ctx.busy&&!ctx.pursuit){const choices=STREET_SCENES.filter(e=>this.eligible(e,ctx));if(choices.length){const scene=choices.find(e=>e.id==='wrong-location'&&!s.played[e.id])||choices[Math.floor(this.random()*choices.length)];s.active={id:scene.id,started:s.time,index:0,interjection:null};a=s.active;}else{s.nextAt=s.time+4;return out;}}
 if(!a)return out;const scene=STREET_SCENES.find(e=>e.id===a.id),elapsed=s.time-a.started;
 while(a.index<scene.beats.length&&elapsed>=a.index*3.5){const [actorId,original,kind,cue]=scene.beats[a.index];const line=a.index===0&&s.played[scene.id]?.count>0?scene.callback:original;this.emit('say',{actorId,line,sceneId:scene.id},ctx,out);this.emit('gesture',{actorId,kind,sceneId:scene.id},ctx,out);if(cue)this.emit('sound',{actorId,cue,sceneId:scene.id},ctx,out);a.index++;}
 if(elapsed>=11){this.finish('completed');if(a.interjection){const action=scene.actions.find(x=>x.id===a.interjection);const actorId=action.actor||scene.cast[0];this.emit('say',{actorId,line:action.reply,sceneId:scene.id},ctx,out);this.emit('gesture',{actorId,kind:action.gesture,sceneId:scene.id},ctx,out);this.emit('sound',{actorId,cue:action.cue,sceneId:scene.id},ctx,out);s.memories[action.memory]=true;this.emit('effect',{sceneId:scene.id,actorId,actionId:action.id,memory:action.memory,trust:action.trust||0,aura:action.aura||0},ctx,out);}else this.emit('say',{actorId:scene.cast[0],line:scene.idle,sceneId:scene.id},ctx,out);this.emit('crowd',{sceneId:scene.id,actorId:scene.cast[0],kind:a.interjection?'small-reaction':'resume'},ctx,out);}return out;
 }
 castPresent(active,ctx){const scene=STREET_SCENES.find(e=>e.id===active.id);if(!scene)return false;const actors=this.actors(ctx),lead=actors[scene.cast[0]];return lead&&!lead.hidden&&scene.cast.every(id=>actors[id]&&!actors[id].hidden&&distance(lead,actors[id])<16);}
 actions(ctx={}){const a=this.state.active;if(!a||a.interjection||ctx.busy||ctx.pursuit||ctx.paused)return [];const elapsed=this.state.time-a.started;if(elapsed<2||elapsed>9.5)return [];const scene=STREET_SCENES.find(e=>e.id===a.id),lead=this.actors(ctx)[scene.cast[0]];if(!lead||distance(ctx.player,lead)>6)return [];return scene.actions.map(x=>({id:`${scene.id}:${x.id}`,label:x.label,sceneId:scene.id,actorId:scene.cast[0]}));}
 act(id,ctx={}){const offered=this.actions(ctx).find(a=>a.id===id);if(!offered)return {ok:false,reason:'That moment has moved on.'};this.state.active.interjection=id.split(':')[1];return {ok:true,pending:true};}
 finish(status){const s=this.state,a=s.active;if(!a)return;const previous=s.played[a.id];s.played[a.id]={at:s.time,count:(previous?.count||0)+(status==='completed'?1:0),status};s.log.push({id:a.id,at:s.time,status,interjection:a.interjection});s.log=s.log.slice(-40);s.active=null;s.nextAt=s.time+(status==='completed'?16+this.random()*12:35);}
 snapshot(){return clone(this.state);}
 load(raw){try{const s=clone(raw);if(s.version!==1||!Number.isFinite(s.time)||!Number.isFinite(s.rng)||!Number.isFinite(s.nextAt)||!s.played||!s.memories||!Array.isArray(s.log)||s.active&&!STREET_SCENES.some(e=>e.id===s.active.id))return false;if(s.active){const e=STREET_SCENES.find(e=>e.id===s.active.id);if(!Number.isFinite(s.active.started)||!Number.isInteger(s.active.index)||s.active.index<0||s.active.index>e.beats.length||s.active.interjection&&!e.actions.some(a=>a.id===s.active.interjection))return false;}this.state=s;return true;}catch{return false;}}
}
